INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ich bei der Preisbestimmung immer vom Endpreis ausgehe?', 2, '[{"text": "Ja", "correct": true, "because": "Rückwärtskalkulation startet beim Verkaufspreis"}, {"text": "Nein", "correct": false, "because": "Endpreis ist Ausgangspunkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor wird zuerst vom Zielpreis abgezogen?', 3, '[{"text": "Handelsspanne", "correct": true, "because": "Bestimmt Händlergewinn"}, {"text": "Produktionskosten", "correct": false, "because": "Später berechnet"}, {"text": "Transportkosten", "correct": false, "because": "Weiter unten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente berücksichtige ich bei der Preisfindung?', 5, '[{"text": "Rabatte", "correct": true, "because": "Beeinflussen Endpreis"}, {"text": "Skonti", "correct": true, "because": "Für Zahlungsfristen"}, {"text": "Firmenfarben", "correct": false, "because": "Kein Preisfaktor"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rückwärts vom Verkaufspreis werden Margen abgezogen. b) Sie ignoriert Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Kosten werden berücksichtigt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Preisberechnung rückwärts?', 4, '[{"text": "Mehrwertsteuer", "correct": false, "because": "Muss abgezogen werden"}, {"text": "Händlermarge", "correct": false, "because": "Teil der Kalkulation"}, {"text": "Produktfarbe", "correct": true, "because": "Kein Preisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Skonti immer berücksichtigt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Zahlungsfristen relevant"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten ziehe ich nach der Händlermarge ab?', 4, '[{"text": "Mehrwertsteuer", "correct": true, "because": "Steuer vor Nettobetrag"}, {"text": "Lohnkosten", "correct": false, "because": "Später in Produktion"}, {"text": "Marketingkosten", "correct": false, "because": "Weiter unten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Preisberechnung rückwärts immer den Gewinn maximiert. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Hängt von Markt ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Preisberechnung rückwärts dasselbe wie die Vorwärtskalkulation?', 2, '[{"text": "Nein", "correct": true, "because": "Rückwärts vom Preis, vorwärts von Kosten"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rabatte berücksichtige ich bei der Preisfindung?', 5, '[{"text": "Mengenrabatt", "correct": true, "because": "Beeinflusst Endpreis"}, {"text": "Zielrabatt", "correct": true, "because": "Für bestimmte Kunden"}, {"text": "Bürokosten", "correct": false, "because": "Keine Rabattart"}, {"text": "Transportrabatt", "correct": false, "because": "Selten verwendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Preisberechnung?', 4, '[{"text": "Marktpreis", "correct": true, "because": "Bestimmt Zielpreis"}, {"text": "Schnelle Berechnung", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Produktdesign", "correct": false, "because": "Kein Preisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rückwärts kalkulierte Preise berücksichtigen Rabatte. b) Sie ignorieren die Mehrwertsteuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Steuer wird abgezogen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Preisberechnung rückwärts?', 3, '[{"text": "Verkaufspreis", "correct": false, "because": "Ausgangspunkt"}, {"text": "Margen", "correct": false, "because": "Bestimmen Gewinn"}, {"text": "Verpackungsfarbe", "correct": true, "because": "Kein finanzieller Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich den Einkaufspreis berechne?', 4, '[{"text": "Vom Verkaufspreis Margen und Steuern abziehen", "correct": true, "because": "Führt zum Netto"}, {"text": "Nur Kosten addieren", "correct": false, "because": "Vorwärtskalkulation"}, {"text": "Zufällige Werte", "correct": false, "because": "Unpräzise"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Preisberechnung rückwärts nur für den Einzelhandel gilt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Großhandel, Dienstleistungen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, den Zielpreis realistisch zu setzen?', 4, '[{"text": "Marktanalyse", "correct": true, "because": "Berücksichtigt Wettbewerb"}, {"text": "Zufallswahl", "correct": false, "because": "Unrealistisch"}, {"text": "Maximale Marge", "correct": false, "because": "Ignoriert Markt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird die Mehrwertsteuer immer abgezogen?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der Kalkulation"}, {"text": "Nein", "correct": false, "because": "Steuer ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Preisberechnung rückwärts?', 5, '[{"text": "Marktorientierung", "correct": true, "because": "Passt an Wettbewerb"}, {"text": "Gewinnkontrolle", "correct": true, "because": "Margen klar definiert"}, {"text": "Schnellere Produktion", "correct": false, "because": "Kein Preisfaktor"}, {"text": "Bessere Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Preisberechnung unwichtig?', 3, '[{"text": "Steuersätze", "correct": false, "because": "Beeinflussen Netto"}, {"text": "Kundenzielgruppe", "correct": false, "because": "Bestimmt Preis"}, {"text": "Produktname", "correct": true, "because": "Kein finanzieller Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich den Einkaufspreis für ein Produkt finde?', 4, '[{"text": "Verkaufspreis minus Margen und Steuern", "correct": true, "because": "Liefert Nettobetrag"}, {"text": "Kosten einfach addieren", "correct": false, "because": "Vorwärts, nicht rückwärts"}, {"text": "Preis schätzen", "correct": false, "because": "Ungenau"}]');
